define("mod_contentcreator/card-quality",[],function(){"use strict";var e={vet:{"hook-scenario":{intent:"Put the learner on the job at a named time and place, watching a physical thing go wrong, and make them commit to what they would do with their hands before any explanation arrives.",prompt:"Open on a named worker, a clock time and a place on site inside the first fifteen words of sceneParts[0].text.\nEvery panel must show something being physically done or read — a tool picked up, a gauge read, a guard checked, a body on the floor — not a conversation about the work. If a panel could be filmed only as people talking, rewrite it.\nAt least one panel carries a reading with its unit from the reference material: the depth, the voltage, the rate, the load, the temperature.\nName what is at risk in physical terms — a person, a load, a machine, a job that gets done twice — never reputation, trust or satisfaction.\nsceneParts[3].text ends on a direct question to the learner in second person, ending in a question mark. The people in the scene must not work it out themselves.\nkeyTakeaway states the load-bearing figure and what it changes on the job, in two sentences.",criteria:[{id:"VET-HOOK-1",rule:"sceneParts[0].text names a person, a clock time or shift point, and a place on site within its first fifteen words.",check:"judgement",polarity:null,re:null},{id:"VET-HOOK-2",rule:"Every one of the four panels contains at least one physical act the learner or a named person performs — something an assessor standing three metres away would see.",check:"judgement",polarity:null,re:null},{id:"VET-HOOK-3",rule:"At least one panel carries a measurement or threshold with its unit, taken from the reference material.",check:"judgement",polarity:null,re:null},{id:"VET-HOOK-4",rule:"sceneParts[3].text ends on a decision the learner must make, written as a direct second-person question; the characters do not resolve it.",check:"regex",polarity:"require",re:new RegExp("\\b(you|your)\\b[^?]{0,120}\\?\\s*$","i")},{id:"VET-HOOK-5",rule:"The stake named in the card lands on a body, a machine, a load or a job that has to be done twice — never on trust, credibility, satisfaction or morale.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|satisfaction|credibility|reputation|dissatisfaction|morale|productivity|engagement)\\b","i")},{id:"VET-HOOK-6",rule:"keyTakeaway is two sentences, carries the card's load-bearing number, and says what that number changes about what the learner does.",check:"judgement",polarity:null,re:null},{id:"VET-HOOK-7",rule:"The stake names a specific body part or a specific piece of equipment/material at risk - not just the fact that harm is possible.",check:"regex",polarity:"require",re:new RegExp("\\b(hand|arm|leg|back|eye|skin|lung|finger|foot|hip|knee|spine|head|chest|shoulder|ankle|wrist)\\b|\\b(machine|load|panel|circuit|scaffold|vehicle|crane|forklift|hoist|conveyor|generator|compressor|cylinder|tank|pipeline|wiring|structure|ladder|harness)\\b","i")},{id:"VET-HOOK-8",rule:"Somewhere in the scene, a real pressure pushes toward the shortcut - a supervisor, a deadline, a mate who has already moved on - not a technical ambiguity sitting in isolation.",check:"regex",polarity:"require",re:new RegExp("\\b(supervisor|foreman|boss|site manager|leading hand|client|deadline|behind schedule|running late|told (you|him|her) to|said it (was|'d be) fine|already signed off|crew (is|are) waiting|mate said)\\b","i")}]},"concept-explainer":{intent:"Explain how the thing actually works on the job, under the real instrument that governs it, so the learner can do the task correctly rather than describe it.",prompt:"conceptInsights[0] answers the question sceneParts[3] left open on Card 1, and opens on the thing that contradicts the obvious guess.\nEvery panel states a mechanism with its parts named and the figure attached: what acts on what, in what order, at what reading. A panel that only says a thing is important is not a panel.\nheading names the Act, regulation, code of practice or standard this sits under, as a worker would say it — not by section number. If the topic genuinely sits under no such document, return heading as an empty string. Never invent an instrument and never restate a fact of the subject as though it were an obligation.\nkeyInfo states the duty this places on the WORKER — what they must do before they touch anything, in plain English. Not what the RTO must evidence.\nsummaryLine ties back to the specific moment on Card 1 by naming the person or the place.",criteria:[{id:"VET-CONCEPT-1",rule:"heading is a citable instrument or an empty string; it is never a restatement of the card title or an invented obligation.",check:"regex",polarity:"require",re:new RegExp("(Act|Regulations?|Code of Practice|AS\\/NZS \\d|AS \\d|ISO \\d|Standard)\\b")},{id:"VET-CONCEPT-2",rule:"keyInfo states a duty on the worker, expressed as something they do or must not do before proceeding.",check:"judgement",polarity:null,re:null},{id:"VET-CONCEPT-3",rule:"Each of the three conceptInsights states a mechanism with its intermediate step named and a figure attached, not an outcome with adjectives on it.",check:"judgement",polarity:null,re:null},{id:"VET-CONCEPT-4",rule:"conceptInsights[0] opens by correcting the guess the learner is most likely to have made at the end of Card 1.",check:"judgement",polarity:null,re:null},{id:"VET-CONCEPT-5",rule:"summaryLine names the person, place or object from Card 1; it is not identical or near-identical to keyInfo or to the heading.",check:"judgement",polarity:null,re:null},{id:"VET-CONCEPT-6",rule:"Every technical term is defined in worker's language within twenty words of its first use on the card.",check:"judgement",polarity:null,re:null},{id:"VET-CONCEPT-7",rule:"Somewhere in the explanation, what goes wrong without this concept is stated directly - the mechanism is not taught in isolation from its consequence.",check:"regex",polarity:"require",re:new RegExp("\\b(if (you|it|this) (don't|doesn't|isn't|aren't|fails?)|without this|skip this and|get this wrong and|left unchecked)\\b","i")}]},"mental-model":{intent:"Give the learner the procedure of the work, ending in something signable that exists after they walk away, and name the point at which the job stops being theirs.",prompt:"Write the steps of the job, not the steps of talking about the job. Banned as a sequence: assess the need, explain the concept, tailor the advice, monitor the feedback, keep your knowledge current.\nAt least three of the four or five steps must operate on a number or a named thing: the reading you take, the torque figure, the tool you use, the box you tick.\nOne step is a branch the learner chooses before the next step means anything: two paths, the condition that separates them, and what each one costs.\nOne step names the stop point — the reading, condition or time at which this stops being the learner's job — and the named role they tell.\nThe final step's detail must name what now exists that did not exist before: the completed form, the hung tag, the logged reading, the signed permit, the entry in the named system.\nAn assessor watching should be able to tick every step off from what you wrote, and say at which step the learner would stop and do something different.",criteria:[{id:"VET-MODEL-1",rule:"The final step's detail names a physical or documentary artefact that persists after the learner walks away.",check:"judgement",polarity:null,re:null},{id:"VET-MODEL-2",rule:"At least three of the steps operate on a number or a named tool, material or instrument.",check:"judgement",polarity:null,re:null},{id:"VET-MODEL-3",rule:"One step names the stop point with both its threshold and the role the learner tells.",check:"judgement",polarity:null,re:null},{id:"VET-MODEL-4",rule:"No step's only verb is a talking or noticing verb.",check:"regex",polarity:"forbid",re:new RegExp("^(Discuss|Explain|Consider|Understand|Communicate|Review|Observe|Reflect|Monitor|Educate)\\b","i")},{id:"VET-MODEL-5",rule:"One step is a branch: two named paths, the condition that separates them, and what each path costs.",check:"judgement",polarity:null,re:null},{id:"VET-MODEL-6",rule:"An assessor could tick each step off from three metres away without hearing what was said.",check:"judgement",polarity:null,re:null},{id:"VET-MODEL-7",rule:"At least one step states WHY it matters, not just what to do - a causal reason, not just an instruction.",check:"regex",polarity:"require",re:new RegExp("\\b(because|otherwise|which means|so that|if not)\\b","i")}]},"applied-scenario":{intent:"Bring the same named worker and the same job back later, run them into the edge of the rule Card 3 taught, and resolve it by naming the physical thing they do.",prompt:'Same named person and same job as Card 1, later the same day or on the next shift. The place may move — a different bay, vehicle, room or site — but the learner and the task carry over.\nsceneParts[0].text opens by naming what has changed since Card 1: the time now, and what has moved, been fitted, been signed or gone wrong since.\nsceneParts[2].text introduces a complication the rule from Card 3 does not cleanly cover — the reading between the thresholds, the tool that is not there, the tag already hanging — and ends on the learner deciding, as a direct question.\nsceneParts[3].text resolves it by naming the thing: the figure, the setting, the tool, the form, the person called. Never "you take appropriate action".\nSentence three of each panel says what it costs if you do not, named on a body, a machine, a load or a job that has to be done twice.',criteria:[{id:"VET-APPLIED-1",rule:"The same named person from Card 1 appears in sceneParts[0].text, with the elapsed time or shift named.",check:"judgement",polarity:null,re:null},{id:"VET-APPLIED-2",rule:"At least one teachable specific from Card 2 or Card 3 reappears here, applied rather than restated.",check:"judgement",polarity:null,re:null},{id:"VET-APPLIED-3",rule:"sceneParts[2].text ends on a direct second-person question about a case the Card 3 rule does not cleanly cover.",check:"regex",polarity:"require",re:new RegExp("\\b(you|your)\\b[^?]{0,120}\\?\\s*$","i")},{id:"VET-APPLIED-4",rule:"sceneParts[3].text resolves the complication by naming the specific action, figure, tool or person — not a category.",check:"judgement",polarity:null,re:null},{id:"VET-APPLIED-5",rule:"No panel ends with the learner reflecting, realising or feeling motivated; every panel ends on something done or something at stake.",check:"regex",polarity:"forbid",re:new RegExp("\\b(reflect|realise|realize|motivates|appreciates|feels more (prepared|confident))\\b","i")},{id:"VET-APPLIED-6",rule:"The cost named in each panel lands on a body, a machine, a load or a job redone.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|satisfaction|credibility|reputation|dissatisfaction|morale)\\b","i")},{id:"VET-APPLIED-7",rule:"The scene continues the SAME named worker introduced in the hook-scenario card, not a new unnamed person.",check:"continuity",polarity:"require",re:null}]},mistakes:{intent:"Name the five errors a competent tradesperson actually makes at the edge of their competence, each with the number they used and the number it should have been, and each landing on a person, a machine or a job done twice.",prompt:"A mistake is a thing done wrongly, not an attitude held wrongly. Banned as an opening: Ignoring…, Neglecting…, Overlooking…, Failing to…, Rushing…, Assuming all… .\nAt most one of the five may be a communication or paperwork habit. The other four are errors of substance: the wrong figure, the wrong threshold, the missed step, the rule applied to the wrong case.\nEach mistake names the specific wrong action with its number where it has one. Each consequence names the specific technical result and the number it should have been.\nSentence three of each consequence makes it land on a real person on this job: name who is standing there when it goes wrong and what it costs them, in plain words a worker would use.\nNo two of the five consequences may end on the same outcome.\nThese are errors a knowledgeable person makes. If a beginner would not make it, it is worth teaching.",criteria:[{id:"VET-MISTAKES-1",rule:"No mistake string opens with a character-flaw gerund.",check:"regex",polarity:"forbid",re:new RegExp("^(Ignoring|Neglecting|Overlooking|Failing to|Rushing|Not caring|Assuming all)\\b","i")},{id:"VET-MISTAKES-2",rule:"At least four of the five consequences carry a numeric or named-entity token — the figure used and the figure it should have been.",check:"judgement",polarity:null,re:null},{id:"VET-MISTAKES-3",rule:"Every consequence lands on a body, a machine, a load or a job that has to be done twice — never on trust, satisfaction, credibility or morale.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|satisfaction|credibility|reputation|dissatisfaction|morale|outcomes|effectiveness)\\b","i")},{id:"VET-MISTAKES-4",rule:"At most one of the five is a communication or paperwork habit; the other four are errors of substance in the work.",check:"judgement",polarity:null,re:null},{id:"VET-MISTAKES-5",rule:"No two consequences end on the same outcome.",check:"judgement",polarity:null,re:null},{id:"VET-MISTAKES-6",rule:"Each mistake is one a knowledgeable person makes at the edge of their competence, not one only a careless person makes.",check:"judgement",polarity:null,re:null},{id:"VET-MISTAKES-7",rule:"At least one item ties back to the named worker or moment from the hook-scenario card, instead of the mistakes list floating free of the pack's story.",check:"continuity",polarity:"require",re:null}]},"competency-summary":{intent:"Ten items a supervisor could sign off or refuse from the other side of the yard — five observable acts of the trade, five specific wrong beliefs that get people hurt.",prompt:'Each goodItems[].text is a verb-first act a supervisor could watch someone do and say yes or no to, in six to ten words. "Communicates clearly" fails that. "Checks the batch number against the run sheet before the first pour" passes.\nAt most one of the five may be about how you talk to people.\nEach goodItems[].benefit says what it looks like on the job when this is done properly, in the words a supervisor would use signing it off — not an abstract virtue, and never "improves outcomes".\nEach badItems[].text names the specific wrong belief, not the vice: "Thinking the tag is the isolation", not "Assuming one size fits all".\nEach badItems[].consequence names what physically happens as a result — to a person, a machine, a load, or a job that gets done twice.\nDo not repeat any item from Card 5. These ten are the pack\'s argument compressed, not a second mistakes card.',criteria:[{id:"VET-SUMMARY-1",rule:"Every goodItems[].text is verb-first, six to ten words, and names an object a supervisor can see.",check:"judgement",polarity:null,re:null},{id:"VET-SUMMARY-2",rule:"No goodItems[].text or benefit has a virtue as its head noun.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|confidence|communication|collaboration|professionalism|integrity|reputation|credibility)\\b","i")},{id:"VET-SUMMARY-3",rule:"At most one of the five goodItems is about how you talk to people.",check:"judgement",polarity:null,re:null},{id:"VET-SUMMARY-4",rule:"Each badItems[].text names a specific wrong belief about the work, not a character flaw.",check:"regex",polarity:"forbid",re:new RegExp("^(Ignoring|Neglecting|Overlooking|Failing to|Assuming all|Not caring)\\b","i")},{id:"VET-SUMMARY-5",rule:"Each badItems[].consequence names a physical result — a person, a machine, a load or a job redone.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|satisfaction|credibility|reputation|dissatisfaction|morale|outcomes|effectiveness)\\b","i")},{id:"VET-SUMMARY-6",rule:"No item duplicates an item from the mistakes card or another item on this card.",check:"judgement",polarity:null,re:null},{id:"VET-SUMMARY-7",rule:"The card closes the loop on the hook-scenario's named worker or incident somewhere in its items, instead of reading as a context-free checklist.",check:"continuity",polarity:"require",re:null}]},"decision-point":{intent:"Make the learner discriminate between two things a competent tradesperson would actually do on this job, at a threshold, with the reading in front of them.",prompt:'Write the question as a real situation on the job in twenty-two to thirty-two words, second person, with the reading, the load, the time or the setting in it. Not "How do you ensure…".\nAll four options are ten to sixteen words and the same level of detail, and each names a specific physical action, tool or figure. No option is a conversation.\nBuild the three wrong answers from real misconceptions, or from the right answer to a neighbouring case — a rule applied at the wrong threshold is the best distractor there is.\nAt least two options must be things a competent tradesperson might actually choose.\nDo not append a justification or benefit clause to the correct answer that the wrong answers do not also have; that reasoning goes in feedback.\nEvery option\'s feedback says why someone would believe it, then names exactly what is wrong, and contains a fact — a figure, a tool, a standard. Feedback that only predicts a bad outcome teaches nothing.',criteria:[{id:"VET-DECISION-1",rule:"All four options are 10-16 words and the correct one is within ±30% of the mean length of the three distractors.",check:"judgement",polarity:null,re:null},{id:"VET-DECISION-2",rule:"No option contains an absolutist strawman marker.",check:"regex",polarity:"forbid",re:new RegExp("\\b(only|solely|all|never|ignore|overlook|rely solely)\\b","i")},{id:"VET-DECISION-3",rule:"Every option names a physical action, tool, reading or figure — none is a conversational or advisory act.",check:"judgement",polarity:null,re:null},{id:"VET-DECISION-4",rule:"At least one distractor is the correct answer to a neighbouring case — the same rule at a different threshold — and its feedback names the threshold that separates them.",check:"judgement",polarity:null,re:null},{id:"VET-DECISION-5",rule:"Every feedback string contains a teachable specific — a figure, a tool, a standard or a named step.",check:"judgement",polarity:null,re:null},{id:"VET-DECISION-6",rule:'The question is a situation with a value in it, not a "how do you ensure" stem.',check:"regex",polarity:"forbid",re:new RegExp("^(How do you ensure|How can you ensure|What is the best way to)","i")},{id:"VET-DECISION-7",rule:'The situation stem puts the SAME named worker from the hook-scenario back in the moment, not a generic unnamed "a worker".',check:"continuity",polarity:"require",re:null}]}},workplace:{"hook-scenario":{intent:"Put the learner at their own workstation with a real ticket, order or customer in front of them, show what the error costs in a unit the business counts, and make them commit before the explanation.",prompt:'Open on a named customer or colleague, a clock time, and the channel or system the work arrived through — the queue, the counter, the ticket, the inbox — inside the first fifteen words of sceneParts[0].text.\nOne panel must state what this costs in a unit this organisation counts: minutes, callbacks, returns, rework items, queue position, escalations, dollars, a missed cut-off. "Costs the business money" and "reduces efficiency" are not costs.\nEvery panel must name at least one thing that belongs only to this subject — the product, the figure, the threshold, the named method — so the card would not survive being dropped into a pack about a different subject.\nDo not use unit of competency, performance criteria, evidence, assessor or deemed competent anywhere on this card.\nsceneParts[3].text ends on a decision the learner must make, addressed to them, as a direct question ending in a question mark.\nkeyTakeaway states the figure the decision turns on and what it changes about what the learner does next time.',criteria:[{id:"WP-HOOK-1",rule:"sceneParts[0].text names a person, a clock time, and the system, queue or channel the work came in on, within its first fifteen words.",check:"judgement",polarity:null,re:null},{id:"WP-HOOK-2",rule:"At least one panel states the cost of getting this wrong as a number attached to a unit the business counts.",check:"judgement",polarity:null,re:null},{id:"WP-HOOK-3",rule:"The card passes the swap test — it carries at least three nouns belonging only to this subject and could not be dropped word for word into a pack about another subject.",check:"judgement",polarity:null,re:null},{id:"WP-HOOK-4",rule:"sceneParts[3].text ends on a decision the learner must make, as a direct second-person question; the characters do not resolve it.",check:"regex",polarity:"require",re:new RegExp("\\b(you|your)\\b[^?]{0,120}\\?\\s*$","i")},{id:"WP-HOOK-5",rule:"No RTO or assessment vocabulary appears anywhere on the card.",check:"regex",polarity:"forbid",re:new RegExp("\\b(unit of competency|performance criteria|assessor|deemed competent|evidence requirement|range statement|foundation skills)\\b","i")},{id:"WP-HOOK-6",rule:"keyTakeaway is two sentences carrying the figure the business decision turns on, and it is not a statement about communication, trust or understanding.",check:"judgement",polarity:null,re:null},{id:"WP-HOOK-7",rule:"A second, competing pressure is stacking up while the main problem is being handled - not one clean interaction in an empty room.",check:"regex",polarity:"require",re:new RegExp("\\b(meanwhile|at the same time|while (you|she|he)|another (customer|call|email)|phone (is ringing|rings|keeps ringing)|your manager|line (is|'s) backing up|more (customers|calls) waiting)\\b","i")},{id:"WP-HOOK-8",rule:"The other person in the scene behaves unreasonably in some specific way - raised voice, refusal, interruption - not a calm, cooperative interaction throughout.",check:"regex",polarity:"require",re:new RegExp("\\b(raises? (her|his|their) voice|interrupts?|refuses? to|insists?|won't accept|demands?|threatens? to|crosses? (her|his|their) arms|slams?|snaps?)\\b","i")}]},"concept-explainer":{intent:"Teach the technical subject that the business decision rests on, name the internal document only if one genuinely exists, and state what the requirement is protecting in a number.",prompt:'conceptInsights[0] answers the question sceneParts[3] left open on Card 1, and leads with the correction: the thing that contradicts the obvious guess, then the explanation.\nEvery panel states a mechanism with its parts named and the figure attached. "Carbohydrate becomes glucose, glucose becomes ATP without oxygen, and that pathway runs for about ninety seconds" is a mechanism. "Carbohydrates are important for energy" is a category label.\nheading names the internal policy, SOP or service standard this sits under, by its real name — the document a colleague could actually be sent to. Name one ONLY if the reference material or the trainer instructions name one. If they do not, return heading as an EMPTY STRING. An invented policy name sends staff hunting for a file that does not exist.\nkeyInfo states what the business requires and what it is protecting — the cost, the customer commitment or the cut-off it exists to prevent — with the number the source gives.\nsummaryLine names what this rests on from earlier in the pack, and ties back to the person on Card 1.',criteria:[{id:"WP-CONCEPT-1",rule:"heading is an exact string from the uploaded reference material or the trainer instructions, or it is an empty string.",check:"judgement",polarity:null,re:null},{id:"WP-CONCEPT-2",rule:"keyInfo carries a number attached to a business unit and names what that requirement protects.",check:"judgement",polarity:null,re:null},{id:"WP-CONCEPT-3",rule:"Each of the three conceptInsights states a mechanism with its intermediate step named and a figure attached.",check:"judgement",polarity:null,re:null},{id:"WP-CONCEPT-4",rule:"conceptInsights[0] opens on the correction, not the definition — the sentence that tells the reader the thing they assumed is wrong.",check:"judgement",polarity:null,re:null},{id:"WP-CONCEPT-5",rule:"The card survives the swap test — at least three domain nouns from the source, and no panel that would read identically in a pack about another subject.",check:"judgement",polarity:null,re:null},{id:"WP-CONCEPT-6",rule:"No sentence ends in a trailing benefit clause that adds no information.",check:"regex",polarity:"forbid",re:new RegExp(",\\s*(which|leading to|making sure|ensuring|helping to)\\b[^.]*\\b(satisfaction|outcomes|success|effectiveness|trust|results|performance)\\b","i")},{id:"WP-CONCEPT-7",rule:"Somewhere in the explanation, what goes wrong without this concept is stated directly.",check:"regex",polarity:"require",re:new RegExp("\\b(if (you|it|this) (don't|doesn't|isn't|aren't|fails?)|without this|skip this and|get this wrong and|left unchecked)\\b","i")}]},"mental-model":{intent:"Give a new starter a procedure they can follow without asking where anything lives, ending at the point where the work leaves their hands and enters someone else's queue.",prompt:'Write the steps of the work, not the steps of talking about the work. Banned as a sequence: assess the need, explain the concept, tailor the advice, monitor the feedback, keep your knowledge current.\nEvery step names the actual system, screen, form, queue or report the work happens in, and says what you check before moving on.\nAt least three of the four or five steps must operate on a number or a named field. Step two is "multiply their body weight by ten", not "assess their needs".\nOne step is a branch: two paths, the condition that separates them, and what each one costs in time, rework or money.\nOne step names the handover boundary — the value or condition at which this stops being the learner\'s to decide, and the named role or queue it goes to, with what must be in the note when it goes.\nA colleague who has never done this should be able to follow it without asking where anything lives.',criteria:[{id:"WP-MODEL-1",rule:"At least three steps name the system, screen, queue, form or report the work happens in.",check:"judgement",polarity:null,re:null},{id:"WP-MODEL-2",rule:"At least three steps operate on a number, a threshold or a named quantity.",check:"judgement",polarity:null,re:null},{id:"WP-MODEL-3",rule:"One step names the handover boundary: the threshold, the role or queue it goes to, and what goes in the note.",check:"judgement",polarity:null,re:null},{id:"WP-MODEL-4",rule:"No step's only verb is a talking, noticing or reviewing verb.",check:"regex",polarity:"forbid",re:new RegExp("^(Discuss|Explain|Consider|Understand|Communicate|Review|Observe|Reflect|Monitor|Educate)\\b","i")},{id:"WP-MODEL-5",rule:"One step is a branch with two named paths, the condition separating them, and the cost of each in a business unit.",check:"judgement",polarity:null,re:null},{id:"WP-MODEL-6",rule:"The step sequence would not be identical for an unrelated subject — the steps name this subject's own objects.",check:"judgement",polarity:null,re:null},{id:"WP-MODEL-7",rule:"At least one step states WHY it matters, not just what to do.",check:"regex",polarity:"require",re:new RegExp("\\b(because|otherwise|which means|so that|if not)\\b","i")}]},"applied-scenario":{intent:"Bring the same named customer or colleague back on the same job, hit the case the SOP does not cover, and resolve it by naming the quantity or protocol — with the cost counted in a unit the business watches.",prompt:'Same named person and same piece of work as Card 1 — the same order, ticket, account or customer — later the same day or on the next shift.\nsceneParts[0].text opens by naming what has changed since Card 1: how long has passed, what has been actioned, and where the job now sits in the system.\nOne panel states what this costs in a unit this business counts — minutes, callbacks, returns, a missed cut-off, dollars, a place in the queue.\nsceneParts[2].text introduces a complication the rule from Card 3 does not cleanly cover, and ends on the learner deciding, as a direct question. The taught rule has an edge and this is where the learner meets it.\nsceneParts[3].text resolves it by naming the thing: "you tell her three to five grams a day and no loading phase", not "you recommend a supplement".\nWhere a consequence reaches a customer, name them and say what happened to their day. Never "customer dissatisfaction".',criteria:[{id:"WP-APPLIED-1",rule:"The same named person and the same order, ticket or account from Card 1 appear in sceneParts[0].text, with the elapsed time named.",check:"judgement",polarity:null,re:null},{id:"WP-APPLIED-2",rule:"One panel names the cost in a business unit with a number on it.",check:"judgement",polarity:null,re:null},{id:"WP-APPLIED-3",rule:"sceneParts[2].text ends on a direct second-person question about a case the taught rule does not cleanly cover.",check:"regex",polarity:"require",re:new RegExp("\\b(you|your)\\b[^?]{0,120}\\?\\s*$","i")},{id:"WP-APPLIED-4",rule:"sceneParts[3].text resolves by naming a quantity or a named protocol, not a category.",check:"judgement",polarity:null,re:null},{id:"WP-APPLIED-5",rule:"Where a consequence reaches a customer or colleague, that person is named and what happened to their day is stated.",check:"regex",polarity:"forbid",re:new RegExp("\\b(customers?|clients?|stakeholders)\\b\\s+(may|might|could|feel|experience)","i")},{id:"WP-APPLIED-6",rule:"No panel ends with the learner reflecting on their own learning or the customer admiring them.",check:"regex",polarity:"forbid",re:new RegExp("\\b(reflect|realise|realize|impressed|appreciates|motivates|staying informed)\\b","i")},{id:"WP-APPLIED-7",rule:"The scene continues the SAME named person from the hook-scenario, not a new unnamed customer or colleague.",check:"continuity",polarity:"require",re:null}]},mistakes:{intent:"Name five substantive errors staff actually make in this subject, each costing something the business counts, each landing on a named person, and one of them being an earlier rule applied outside its boundary.",prompt:"A mistake is a thing done wrongly, not an attitude held wrongly. Banned as an opening: Ignoring…, Neglecting…, Overlooking…, Failing to…, Rushing…, Assuming all… .\nAt most one of the five may be a communication or process habit. The other four are errors of substance in the subject: the wrong figure, the wrong threshold, the missed step, the rule applied to the wrong case.\nSentence one of each consequence states the specific business impact with its unit: the minutes, the callback, the return, the credit note, the missed cut-off.\nSentence two names what has to happen now to put it right.\nSentence three names the customer or colleague standing in it and what it cost their day, in the words a colleague would use.\nOne of the five is applying an earlier slide's rule outside the boundary where it holds.\nNo two of the five consequences may end on the same outcome.",criteria:[{id:"WP-MISTAKES-1",rule:"No mistake string opens with a character-flaw gerund.",check:"regex",polarity:"forbid",re:new RegExp("^(Ignoring|Neglecting|Overlooking|Failing to|Rushing|Not caring|Assuming all)\\b","i")},{id:"WP-MISTAKES-2",rule:"At least four of the five consequences carry a number attached to a business unit.",check:"judgement",polarity:null,re:null},{id:"WP-MISTAKES-3",rule:"Each consequence names a real person — a customer or colleague — and what happened to their day, not a plural abstraction.",check:"regex",polarity:"forbid",re:new RegExp("\\b(clients?|customers?|stakeholders)\\s+(may|might|could|feel|experience|are likely)","i")},{id:"WP-MISTAKES-4",rule:"One of the five is an earlier rule applied outside the boundary where it holds, and the boundary is stated.",check:"judgement",polarity:null,re:null},{id:"WP-MISTAKES-5",rule:"No two consequences end on the same outcome, and none ends on trust, satisfaction or confusion.",check:"judgement",polarity:null,re:null},{id:"WP-MISTAKES-6",rule:"At most one of the five is a communication or process habit; the other four are errors of substance in the subject.",check:"judgement",polarity:null,re:null},{id:"WP-MISTAKES-7",rule:"At least one item ties back to the named person or moment from the hook-scenario card.",check:"continuity",polarity:"require",re:null}]},"competency-summary":{intent:"Ten items that state the standard the team is held to and the specific wrong beliefs that cost the business — each benefit and each consequence counted in something the business measures.",prompt:'Each goodItems[].text is a verb-first standard a team leader could watch someone do and say yes or no to, in six to ten words.\nEach goodItems[].benefit names what it saves, prevents or protects, counted concretely: the callback that never happens, the escalation that stops at you, the eight minutes not spent unwinding it. Not an abstract virtue.\nAt most one of the five may be about how you talk to people. The rest are the subject done properly.\nEach badItems[].text names the specific wrong belief, not the vice: "Thinking loading raises the ceiling", not "Assuming one size fits all".\nEach badItems[].consequence names what it costs in a unit the business counts, in fourteen to eighteen words.\nDo not use unit of competency, performance criteria, evidence, assessor or deemed competent anywhere on this card.\nDo not repeat any item from Card 5.',criteria:[{id:"WP-SUMMARY-1",rule:"Every goodItems[].text is verb-first, six to ten words, and names an object or system a team leader can observe.",check:"judgement",polarity:null,re:null},{id:"WP-SUMMARY-2",rule:"At least four of the five goodItems[].benefit contain a business unit or a countable saved event.",check:"judgement",polarity:null,re:null},{id:"WP-SUMMARY-3",rule:"No RTO or assessment vocabulary appears on the card.",check:"regex",polarity:"forbid",re:new RegExp("\\b(unit of competency|performance criteria|assessor|deemed competent|evidence requirement|range statement)\\b","i")},{id:"WP-SUMMARY-4",rule:"Each badItems[].text names a specific wrong belief about the subject, not a character flaw.",check:"regex",polarity:"forbid",re:new RegExp("^(Ignoring|Neglecting|Overlooking|Failing to|Assuming all|Not caring)\\b","i")},{id:"WP-SUMMARY-5",rule:"No goodItems or badItems field terminates on trust, satisfaction, credibility, reputation or morale.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|satisfaction|dissatisfaction|credibility|reputation|morale)\\b","i")},{id:"WP-SUMMARY-6",rule:"No item duplicates an item from the mistakes card or another item on this card.",check:"judgement",polarity:null,re:null},{id:"WP-SUMMARY-7",rule:"The card closes the loop on the hook-scenario's named person somewhere in its items, instead of reading as a context-free checklist.",check:"continuity",polarity:"require",re:null}]},"decision-point":{intent:"Make the learner discriminate between two defensible protocols at a threshold the business decision turns on, using a specific taught here and one taught earlier.",prompt:'Write the question as a real situation in this workplace in twenty-two to thirty-two words, second person, with the figures in it — the quantity, the time on the clock, the value on the order.\nThe options are quantities and named protocols, not attitudes. "Thirty grams of carbohydrate an hour from the first interval" is an option; "tailor your advice to the customer" is not.\nAll four options are ten to sixteen words and the same level of detail. Wrong answers are complete, plausible choices a reasonable colleague might make — never two-word stubs and never absurd.\nAt least two options must be things a competent practitioner might actually choose. The best distractor is the right answer to a neighbouring case: correct at sixty minutes and wrong at forty.\nFrom slide two onward the question must require one specific taught on an earlier slide as well as this slide\'s own material.\nEvery option\'s feedback says why someone would believe it, then names exactly what is wrong, and contains a fact.',criteria:[{id:"WP-DECISION-1",rule:"All four options are 10-16 words and the correct one is within ±30% of the mean distractor length.",check:"judgement",polarity:null,re:null},{id:"WP-DECISION-2",rule:"Every option is a quantity or a named protocol, not an attitude or a communication act.",check:"judgement",polarity:null,re:null},{id:"WP-DECISION-3",rule:"No option contains an absolutist strawman marker.",check:"regex",polarity:"forbid",re:new RegExp("\\b(only|solely|all|never|ignore|overlook|rely solely)\\b","i")},{id:"WP-DECISION-4",rule:"The question carries a figure this slide taught and, from slide two onward, one specific taught on an earlier slide.",check:"judgement",polarity:null,re:null},{id:"WP-DECISION-5",rule:"Every feedback string names why someone would believe the option, then what is specifically wrong, and contains a fact.",check:"judgement",polarity:null,re:null},{id:"WP-DECISION-6",rule:'The question is a situation with numbers in it, not a "how do you ensure" stem, and no two decision-points in the pack test the same discrimination.',check:"judgement",polarity:null,re:null},{id:"WP-DECISION-7",rule:"The situation stem puts the SAME named person from the hook-scenario back in the moment.",check:"continuity",polarity:"require",re:null}]}},pd:{"hook-scenario":{intent:"Put the learner inside a specific conversation that has already half-gone-wrong, and hand them the decision about what to say next before any explanation exists.",prompt:"Open on one named colleague, report or client at a stated moment, in a working relationship with a history — what was let slide, what was said last time, what is due.\nAt least one panel must report the actual words said, in quotation marks, by the learner or by the other person; a paraphrase of a conversation is not a conversation.\nOne panel must say what the other person is probably thinking and why that reading is reasonable from where they sit.\nPanel 4 stops before the resolution and asks the learner directly what they say now, ending in a question mark. The people in the scene must not work it out themselves.\nDo not write a meeting where someone explains a topic to the room. Do not name equipment, worksites, PPE, forms or compliance steps.\nThe keyTakeaway states the move and the order it goes in, not the virtue behind it.",criteria:[{id:"PD-HOOK-1",rule:"Panel 1 names a person, a moment and something at stake within its first fifteen words.",check:"judgement",polarity:null,re:null},{id:"PD-HOOK-2",rule:"At least one panel contains the actual words spoken, in quotation marks.",check:"regex",polarity:"require",re:new RegExp('["“][^"”]{20,}["”]')},{id:"PD-HOOK-3",rule:"One panel states what the other person is thinking or protecting, in their terms, and why it is reasonable.",check:"judgement",polarity:null,re:null},{id:"PD-HOOK-4",rule:"Panel 4 ends on a direct question to the learner and does not resolve the situation.",check:"regex",polarity:"require",re:new RegExp('\\?["”]?\\s*$')},{id:"PD-HOOK-5",rule:"The stake lands on a named individual and a stated stretch of time, never on trust, morale, engagement, culture or team dynamics.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|morale|engagement|team dynamics|culture|rapport|productivity)\\b")},{id:"PD-HOOK-6",rule:"The scene is a judgement call with no correct procedure; nothing on this card can be satisfied by following a checklist or a system.",check:"regex",polarity:"forbid",re:new RegExp("\\b(unit of competency|assessor|evidence requirement|PPE|worksite|toolbox talk|isolation|template|within \\d+ (working )?days)\\b")},{id:"PD-HOOK-7",rule:"At least one physical, sensory detail grounds the scene - a closed door, a pause, a dropped voice - not pure dialogue in a void.",check:"regex",polarity:"require",re:new RegExp("\\b(closes? the door|puts? down (the|his|her) phone|leans? back|leans? forward|goes? quiet|falls? silent|long pause|glances? away|looks? away|arms crossed|voice (drops|shakes)|takes? a (deep )?breath|checks? the (time|clock))\\b","i")},{id:"PD-HOOK-8",rule:"The learner's own internal state is named somewhere - hesitation, dread, rehearsing what to say - not just a neutral narrator describing what they do.",check:"regex",polarity:"require",re:new RegExp("\\b(hesitat\\w*|dread\\w*|rehears\\w*|swallow\\w*|steel\\w* (himself|herself|themselves)|takes? a (deep )?breath|reluctant\\w*|braces? (himself|herself|themselves)|stomach (tightens|drops))\\b","i")}]},"concept-explainer":{intent:"Give the learner a contestable claim about why the obvious move fails in this kind of conversation, with the price of the better move named.",prompt:'Panel 1 answers the question Card 1 left open, and opens on the thing that contradicts the obvious guess about it.\nEach of the three panels must contain a claim an experienced professional could argue against — a stated order of moves, a stated boundary, a stated reason the usual advice fails. A panel nobody could disagree with contains no claim.\nEvery recommended move names its price: what you give up, the ground you lose, the person who will not like it. A move with no downside is advice nobody needed.\nState the mechanism in the room: what your sentence does to the other person, what that makes them do next, and what that costs you two conversations later.\nheading names the model, principle or professional standard this rests on — never an Act, regulation, code of practice or WHS instrument. If the source names none, return an empty string and put the plain requirement in keyInfo.\nDo not invent a timeframe, a ratio or a frequency to sound precise; an unsourced "within 48 hours" or "three positives per correction" is a fabrication, not a specific.',criteria:[{id:"PD-CONCEPT-1",rule:"Each of the three panels contains a claim a thoughtful practitioner could argue against.",check:"judgement",polarity:null,re:null},{id:"PD-CONCEPT-2",rule:"At least one panel names what the recommended move costs the learner.",check:"judgement",polarity:null,re:null},{id:"PD-CONCEPT-3",rule:"Panel 1 states the thing that contradicts the obvious guess, and says what the obvious guess is.",check:"judgement",polarity:null,re:null},{id:"PD-CONCEPT-4",rule:"heading is a named model, principle or professional standard, or an empty string. Never a law, Act, regulation or code, and never a restatement of the card title.",check:"regex",polarity:"forbid",re:new RegExp("\\b(Act|Regulation|Regulations|Code of Practice|AS\\/NZS|WHS|Legislation)\\b")},{id:"PD-CONCEPT-5",rule:"No numeric threshold, frequency or ratio appears unless the reference material supplies it.",check:"judgement",polarity:null,re:null},{id:"PD-CONCEPT-6",rule:"summaryLine refers back to the situation in Card 1 by its own detail, and is not a paraphrase of the heading or of keyInfo.",check:"judgement",polarity:null,re:null},{id:"PD-CONCEPT-7",rule:"Somewhere in the explanation, what goes wrong without this idea is stated directly, in conversational terms - not just the mechanism in the abstract.",check:"regex",polarity:"require",re:new RegExp("\\b(if (you|this) (don't|doesn't|isn't)|without this|the conversation (breaks down|goes sideways)|left unsaid)\\b","i")}]},"mental-model":{intent:"Hand the learner four or five sayable sentences in sequence, each with the signal to watch for in the reply and the branch that decides what comes next.",prompt:'Every step contains the sentence you would actually say, in quotation marks, in words a working professional would use out loud without translating them first.\nEvery step names the signal you are watching for in the reply — what they do with their hands, what they ask, what they do not say — and what you do with each reading.\nOne step is a branch: two readings of the same reply that send you down different routes, and the learner must choose before the next step means anything.\nA step whose only verb is listen, consider, reflect or discuss is not a step. Say what listening looks like here and what you do with what you hear.\nBanned as a sequence: assess the need, explain the concept, tailor the advice, monitor the feedback, keep your knowledge current. That is five ways of saying "have a conversation".\nDo not attach a number, a timeframe or a count to any step unless the reference material gives one — this route has no thresholds and inventing them is fabrication.',criteria:[{id:"PD-MODEL-1",rule:"Every step's detail contains at least one quoted sentence of six words or more.",check:"regex",polarity:"require",re:new RegExp('["“][^"”]{25,}["”]')},{id:"PD-MODEL-2",rule:"Every step names an observable signal in the other person's reply and what each reading means.",check:"judgement",polarity:null,re:null},{id:"PD-MODEL-3",rule:"Exactly one step is a branch the learner chooses between before the following steps apply.",check:"judgement",polarity:null,re:null},{id:"PD-MODEL-4",rule:"No fabricated numeric threshold, frequency, ratio or deadline appears in any step.",check:"judgement",polarity:null,re:null},{id:"PD-MODEL-5",rule:"The sequence is the moves of the conversation, not the stages of having one.",check:"regex",polarity:"forbid",re:new RegExp("^(Assess|Identify|Determine|Explain|Tailor|Monitor|Review|Reflect)\\b")},{id:"PD-MODEL-6",rule:"A reader could use these words tomorrow without rewriting them; nothing in the card is a compliance step, a form or a system.",check:"regex",polarity:"forbid",re:new RegExp("\\b(template|documentation|record it in|policy|procedure|sign off|escalate to|PPE|worksite)\\b")},{id:"PD-MODEL-7",rule:"At least one step refers to what the OTHER person does or says - the sequence is anchored to a real exchange, not the learner's internal process alone.",check:"regex",polarity:"require",re:new RegExp("\\b(they (say|respond|push back|ask|react)|the other person|he says|she says|comes back with)\\b","i")}]},"applied-scenario":{intent:"Return to the same person later, hit them with a complication the model does not cover, and make the learner decide again before the resolution names the actual words used.",prompt:'Same named person and same working relationship as Card 1, at a later, stated point — the next one-to-one, the following Monday, the next time this comes up. Panel 1 opens by naming what has changed since Card 1.\nPanel 2 shows the learner using one specific move from Card 3, in the words from Card 3, and what came back.\nPanel 3 is a complication the model does not cleanly cover — the other person raises something reasonable that the rule did not anticipate — and it ends on the learner deciding, as a direct question ending in a question mark.\nPanel 4 resolves it by naming the thing: the sentence actually said and what it cost. Never "you address their concerns" or "you tailor your approach".\nSay what the good move cost the learner here, in this scene, to a named person.\nDo not introduce a new cast, a new client or an unrelated situation; this renders under a "Continuing the scenario" banner and a new scene reads as a mistake.',criteria:[{id:"PD-APPLIED-1",rule:"The same named person from the hook appears here, and panel 1 states what has changed since.",check:"judgement",polarity:null,re:null},{id:"PD-APPLIED-2",rule:"One panel uses a specific move or quoted sentence taught on Card 2 or Card 3 and reports what came back.",check:"judgement",polarity:null,re:null},{id:"PD-APPLIED-3",rule:"Panel 3 raises a complication the taught rule does not cover and ends on a direct question to the learner.",check:"regex",polarity:"require",re:new RegExp('\\?["”]?\\s*$')},{id:"PD-APPLIED-4",rule:"Panel 4 names the actual sentence or move, not a category of move.",check:"regex",polarity:"require",re:new RegExp('["“][^"”]{20,}["”]')},{id:"PD-APPLIED-5",rule:"The resolution names what the good move cost, and who paid it.",check:"judgement",polarity:null,re:null},{id:"PD-APPLIED-7",rule:"The scene never resolves in instant gratitude or agreement - real difficult conversations don't close that cleanly.",check:"regex",polarity:"forbid",re:new RegExp("\\b(gratefully (accepted|agreed)|immediately (agreed|thanked)|thanked (you|her|him) for the feedback|relieved and grateful|instantly (understood|saw the point)|happily (agreed|accepted))\\b","i")}]},mistakes:{intent:"Name five kind, reasonable moves a capable professional makes in this kind of conversation, and what each one costs a named person later.",prompt:'Each mistake is a specific move made at a specific moment — what was said, when, to whom. Not "did not listen properly".\nThese are errors a capable, well-meaning person makes: the generous move, the fair-sounding move, the move that buys peace today. If a careless person would make it, it is not worth five words here.\nBanned as an opening: Ignoring…, Neglecting…, Overlooking…, Failing to…, Rushing…, Assuming all… .\nAt most two of the five may be about listening or noticing. The rest are errors of judgement, of timing, or of what you committed to and did not do.\nEach consequence lands on a named colleague, report or client over a stated stretch of time — what stops happening, what they stop bringing you. Never on trust, morale, engagement or team dynamics.\nNo two of the five consequences may end on the same outcome.',criteria:[{id:"PD-MISTAKES-1",rule:"No mistake opens with a banned gerund.",check:"regex",polarity:"forbid",re:new RegExp("^(Ignoring|Neglecting|Overlooking|Failing to|Rushing|Assuming all)\\b")},{id:"PD-MISTAKES-2",rule:"Each mistake is a move a capable person makes for a good reason, and the reason is visible.",check:"judgement",polarity:null,re:null},{id:"PD-MISTAKES-3",rule:"At most two of the five concern listening, noticing or attention.",check:"judgement",polarity:null,re:null},{id:"PD-MISTAKES-4",rule:"Each consequence names a person and a stretch of time; none ends on trust, morale, engagement, dynamics or satisfaction.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|morale|engagement|dynamics|satisfaction|dissatisfaction|credibility|reputation)\\b")},{id:"PD-MISTAKES-5",rule:"No two consequences end on the same outcome.",check:"judgement",polarity:null,re:null},{id:"PD-MISTAKES-6",rule:"Each consequence contains a repeatable specific — the sentence that was said, the signal that was missed, or the named model whose boundary was crossed.",check:"judgement",polarity:null,re:null},{id:"PD-MISTAKES-7",rule:"At least one mistake names the learner's own internal shortcut (avoidance, rushing to reassure, rehearsing a script instead of listening) - not only external, procedural errors.",check:"regex",polarity:"require",re:new RegExp("\\b(rush(es|ing)? to (reassure|resolve|fix)|avoid(s|ing)? the (real|actual) (issue|point)|reads? from a script|stops? listening|assumes? (before|without) asking)\\b","i")}]},"competency-summary":{intent:"Compress the slide into five recognisable moments a colleague could see the learner have, against five specific wrong beliefs — not ten virtues.",prompt:'Each goodItem text is a verb-first moment someone could watch you have: what you say, when you say it, in what order. Not a quality you possess.\nEach benefit says what changes in the room or in the relationship afterwards, in the words a trusted colleague would use — the thing that starts or stops happening, and to whom.\nEach badItem text names the specific wrong belief, not the vice: "thinking a softener makes the correction easier to hear", never "poor communication".\nAt most one of the five goodItems may be about how you talk to people in general; the other four are about timing, order, commitment, or what you chose not to say.\nNo goodItem or badItem may repeat a mistake already used on Card 5, in wording or in substance.\nBanned as the head noun of any item: trust, confidence, communication, collaboration, professionalism, integrity, rapport.',criteria:[{id:"PD-SUMMARY-1",rule:"Every goodItem text is verb-first and names an observable moment, not a quality.",check:"regex",polarity:"forbid",re:new RegExp("^(Identif|Explain|Discuss|Adapt|Simplif|Understand|Appreciat|Maintain)\\w*ing\\b")},{id:"PD-SUMMARY-2",rule:"Every badItem names a specific wrong belief a capable person holds, not a character flaw.",check:"regex",polarity:"forbid",re:new RegExp("\\b(neglecting|overlooking|ignoring|failing to|not caring|being careless)\\b","i")},{id:"PD-SUMMARY-3",rule:"No item's head noun is an abstract professional virtue.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|confidence|communication|collaboration|professionalism|integrity|rapport)\\b")},{id:"PD-SUMMARY-4",rule:"Each benefit states what starts or stops happening between two people, not an improvement in an abstraction.",check:"judgement",polarity:null,re:null},{id:"PD-SUMMARY-5",rule:"At most one of the five goodItems is about general communication style.",check:"judgement",polarity:null,re:null},{id:"PD-SUMMARY-6",rule:"No item duplicates a Card 5 mistake or another item in this card.",check:"judgement",polarity:null,re:null},{id:"PD-SUMMARY-7",rule:"At least one item is tied to how the OTHER person responds, not just what the learner does in isolation.",check:"regex",polarity:"require",re:new RegExp("\\b(they (say|respond|push back|ask|react)|the other person|he says|she says|comes back with)\\b","i")}]},"decision-point":{intent:"Force a discrimination between four moves a thoughtful professional would defend, where the difference is timing, order or audience rather than competence.",prompt:'Write the question as a specific moment with the tension already in it: who is in the room, what has just happened, what is due. Never "How do you ensure…".\nAll four options are moves — 10 to 16 words each, the same level of detail, each naming what you actually do or say. Two experienced people should be able to disagree about this for a minute.\nEvery wrong answer is a kind, reasonable move a capable professional would actually make. The best distractor is the right answer to a neighbouring case: right if the audience were different, right if it were the first time, right if nobody else had seen it.\nDo not append a justification or benefit clause to the correct answer that the wrong answers do not also have.\nFeedback on every option says why someone would believe it, then what it costs later, and it must name a sentence, a signal or a named model — not just a bad outcome.\nNo option may be a compliance step, a form, a template or an escalation.',criteria:[{id:"PD-DECISION-1",rule:"The question sets a situation with a live tension and cannot be answered by general good practice.",check:"regex",polarity:"forbid",re:new RegExp("^How do you ensure","i")},{id:"PD-DECISION-2",rule:"All four options are 10-16 words and the correct one is not the longest or the most detailed.",check:"judgement",polarity:null,re:null},{id:"PD-DECISION-3",rule:"Every wrong answer is a move a thoughtful, well-intentioned professional would make; none contains an absolutist marker.",check:"regex",polarity:"forbid",re:new RegExp("\\b(only|solely|all|never|ignore|overlook|rely solely)\\b")},{id:"PD-DECISION-4",rule:"Each option's feedback names why someone would choose it, then what it costs later.",check:"judgement",polarity:null,re:null},{id:"PD-DECISION-5",rule:"Every feedback string contains a PD-typed specific — a quoted sentence, a named observable signal, or a named model with its boundary. Consequences alone do not count.",check:"judgement",polarity:null,re:null},{id:"PD-DECISION-6",rule:"No option resolves the situation with a form, template, escalation or documented process.",check:"regex",polarity:"forbid",re:new RegExp("\\b(template|document|record|file it|policy|HR|escalate|formal warning|performance record)\\b")},{id:"PD-DECISION-7",rule:"The situation stem puts the learner back with the SAME named person from the hook-scenario, not a generic unnamed colleague.",check:"continuity",polarity:"require",re:null}]}},university:{"concept-anchor":{intent:"Give the student a definition they could put in an essay, and a significance statement that names who claimed what, when, and what would make it wrong.",prompt:'conceptDefinition states what the concept IS — the mechanism with its parts named — and must survive being read alone by someone who has not seen the card title. Not why it is interesting, not what it is for.\nsignificance names a person, a year and a claim that could be wrong, and says what changes in how research or practice is designed once the claim is accepted.\nThe three keyTerms render as flip cards: each definition must stand alone without the term in front of it, must not contain the term itself, and must not begin with "this", "it" or "these".\nDistinguish the concept from the thing it is most often confused with, and say what separates them.\nkeyTakeaway carries the load-bearing distinction and says what it changes about how a study is designed or a claim is judged.\nNever write: learn, understand, know, be aware of, appreciate, explore. Never attribute a claim, date or finding to anyone the reference material does not.',criteria:[{id:"UNI-ANCHOR-1",rule:"conceptDefinition is a true statement of what the concept is, readable without the title, stating a mechanism with its parts named.",check:"judgement",polarity:null,re:null},{id:"UNI-ANCHOR-2",rule:"significance names a surname, a four-digit year and a claim that could be false.",check:"regex",polarity:"require",re:new RegExp("\\b[A-Z][a-z]{2,}\\b[^.]{0,40}\\b(1[6-9]\\d{2}|20[0-2]\\d)\\b","i")},{id:"UNI-ANCHOR-3",rule:"Each keyTerm definition stands alone, does not contain the term, and does not open with this, it or these.",check:"regex",polarity:"forbid",re:new RegExp("^(This|It|These)\\b")},{id:"UNI-ANCHOR-4",rule:"The card names the concept it is most often confused with and states what separates them.",check:"judgement",polarity:null,re:null},{id:"UNI-ANCHOR-5",rule:"keyTakeaway states the load-bearing distinction and what it changes about how work is designed or judged — not a professional virtue.",check:"regex",polarity:"forbid",re:new RegExp("\\b(trust|confidence|communication|collaboration|productivity)\\b")},{id:"UNI-ANCHOR-6",rule:"Every name, date and finding is traceable to the reference material.",check:"judgement",polarity:null,re:null},{id:"UNI-ANCHOR-7",rule:"The significance names what changed - a prior view it overturned or revised - not just a neutral description of the finding.",check:"regex",polarity:"require",re:new RegExp("\\b(unlike|whereas|in contrast|counter-?intuitively|overturned|revised|challenged|previously (thought|assumed|believed))\\b","i")}]},"theoretical-framework":{intent:"Give the student two or three citable positions with their owners, their dates, their mechanisms and the case each one handles badly — and show that they do not all agree.",prompt:'Each framework\'s originator field carries a surname (or surnames) and the year the claim was made. Never "Various scholars", "Contemporary theorists" or "Modern measurement theory" — an unattributed framework cannot be cited, checked or argued with, and a student who reproduces it will be marked down for exactly that.\nEach principle states the mechanism with its parts named and the boundary condition under which it holds: what acts on what, in what order, and where the claim stops.\nEach limitation names the specific case the framework handles badly, and must be one an advocate of the framework would concede. "It has been criticised for being reductive" is not a limitation.\nWhere two of the frameworks disagree, say so and say what evidence separates them. Do not present a contested field as settled.\nTake every name and date from the reference material. Never attribute a claim to a person or institution the material does not.\nWorked example - PASS: "Where Festinger (1957) treats the discomfort as the trigger for belief change, Bem (1972) argues there was no discomfort at all - people infer their attitude from their own behaviour the way a bystander would." Worked example - FAIL: "Some theorists focus on internal discomfort, while others focus on behaviour" - same topic, no named positions, no real disagreement stated.\nWorked example - PASS: "Where Festinger (1957) treats the discomfort as the trigger for belief change, Bem (1972) argues there was no discomfort at all - people infer their attitude from their own behaviour the way a bystander would." Worked example - FAIL: "Some theorists focus on internal discomfort, while others focus on behaviour" - same topic, no named positions, no real disagreement stated.\nWorked example - PASS: "Where Festinger (1957) treats the discomfort as the trigger for belief change, Bem (1972) argues there was no discomfort at all - people infer their attitude from their own behaviour the way a bystander would." Worked example - FAIL: "Some theorists focus on internal discomfort, while others focus on behaviour" - same topic, no named positions, no real disagreement stated.',criteria:[{id:"UNI-FRAMEWORK-1",rule:"Every originator field contains at least one capitalised surname and a four-digit year appears in the originator or principle.",check:"regex",polarity:"require",re:new RegExp("\\b[A-Z][a-z]{2,}\\b[^.]{0,40}\\b(1[6-9]\\d{2}|20[0-2]\\d)\\b","i")},{id:"UNI-FRAMEWORK-2",rule:"Every limitation names a specific case, condition or counter-example the framework handles badly.",check:"judgement",polarity:null,re:null},{id:"UNI-FRAMEWORK-3",rule:"Every principle states a mechanism with its parts named plus the boundary condition under which it holds.",check:"judgement",polarity:null,re:null},{id:"UNI-FRAMEWORK-4",rule:"At least two of the frameworks are placed in tension with each other, with what separates them named.",check:"judgement",polarity:null,re:null},{id:"UNI-FRAMEWORK-5",rule:"No name, institution, date or finding appears that is not in the reference material.",check:"judgement",polarity:null,re:null},{id:"UNI-FRAMEWORK-6",rule:"The frameworks are distinct positions, not the same claim in three vocabularies.",check:"judgement",polarity:null,re:null}]},"analytical-lens":{intent:"Give the student five moves that change what they see in the material — each anchored to a named case, study or figure that shows the move paying off.",prompt:"Write exactly five considerations. Each names a case, study, researcher, year or worked figure, and says what applying that lens reveals that a naive reading misses.\nA consideration that only names a thing to bear in mind is not a lens — it is a reminder. Every item must end somewhere different from where it started.\nAt least one item names a methodological artefact by its name and says how it is detected: the confound with a name, the design that separates it, the pattern that gives it away.\nDo not restate a framework's principle from Card 2. These are moves the reader makes on evidence, not positions in the literature.\nThe heading names the analytic move the card teaches, not the topic of the pack.\nNever write: learn, understand, know, be aware of, appreciate, explore.",criteria:[{id:"UNI-LENS-1",rule:"Each of the five considerations contains at least one proper noun, year or numeric token.",check:"judgement",polarity:null,re:null},{id:"UNI-LENS-2",rule:"Each consideration states what the lens reveals that a naive reading misses, not merely what to bear in mind.",check:"judgement",polarity:null,re:null},{id:"UNI-LENS-3",rule:"At least one item names a methodological artefact or confound by name and says how it is detected.",check:"judgement",polarity:null,re:null},{id:"UNI-LENS-4",rule:"No consideration restates a principle already given on Card 2.",check:"judgement",polarity:null,re:null},{id:"UNI-LENS-5",rule:"The heading names the analytic move, not the topic, and is not a substring of the pack title.",check:"judgement",polarity:null,re:null},{id:"UNI-LENS-6",rule:"The lens's own limitation is named somewhere - what it cannot explain or where it breaks down - not presented as a universal tool.",check:"regex",polarity:"require",re:new RegExp("\\b(fails? to (account|explain)|cannot explain|blind spot|does not capture|breaks? down when|limit(ation|s) of this)\\b","i")}]},"ethics-considerations":{intent:"Present five ethical dimensions as live trade-offs in this discipline's research practice, each with a stated cost and a stated party who bears it.",prompt:"Write exactly five dimensions. Each description names what is traded against what and who bears the cost — not that the dimension deserves attention.\nA reader must be able to state the opposing position after reading the description. If nobody could argue the other side, the item has no ethics in it.\nAt least two dimensions must be specific to this discipline's actual research or professional practice — the consent problem this method creates, the population this design excludes, the finding this field is under pressure to produce. Not the generic four principles.\nName the party who pays: the participant, the excluded population, the future reader of the literature, the practitioner who inherits the guidance.\nDo not write that researchers must ensure, consider, or handle something appropriately. State the conflict and leave it unresolved where the field leaves it unresolved.\nEvery dimension must be distinct; two items describing the same trade-off in different words is one item.",criteria:[{id:"UNI-ETHICS-1",rule:"Each description names what is traded against what.",check:"judgement",polarity:null,re:null},{id:"UNI-ETHICS-2",rule:"Each description names the party who bears the cost.",check:"judgement",polarity:null,re:null},{id:"UNI-ETHICS-3",rule:"At least two dimensions are specific to this discipline's own research or professional practice, not the generic principles.",check:"judgement",polarity:null,re:null},{id:"UNI-ETHICS-4",rule:"A reader can state the opposing position from what is written.",check:"judgement",polarity:null,re:null},{id:"UNI-ETHICS-5",rule:"The five dimensions are distinct trade-offs, not one trade-off named five ways.",check:"judgement",polarity:null,re:null},{id:"UNI-ETHICS-6",rule:"A genuine trade-off is named - competing interests or values in real tension - not a single correct answer dressed up as a dilemma.",check:"regex",polarity:"require",re:new RegExp("\\btrade-?offs?\\b|\\bcompeting (interests?|values?|obligations?)\\b|\\bat the expense of\\b|\\bno clean answer\\b|\\breasonable people disagree\\b","i")}]},"case-study-1":{intent:"Give the student a fully specified case with a wrinkle the obvious reading cannot absorb, and three prompts that require adjudication rather than recall.",prompt:"Write the context with names, dates, institutions and figures taken from the reference material. A case with no particulars is an illustration, not a case.\nThe context must contain at least one fact that resists the obvious reading — the result that runs the wrong way, the sample that should not have behaved like that, the measure that worked when it should not have. The wrinkle is what makes the case worth analysing.\nThe three analysisPrompts must each require the student to weigh, adjudicate or falsify, and each must use a different stem: one asking which of two readings the evidence supports, one asking what would have to be true for the alternative to hold, one asking what evidence would settle it.\nNo prompt may have a single lookup answer available from Card 1 or Card 2.\nkeyInsight states a claim that could be wrong and names what it rests on. It must not restate the conceptDefinition from Card 1.\nDo not resolve the case cleanly. This case is designed to be contradicted by the second one.",criteria:[{id:"UNI-CASE1-1",rule:"The context carries named particulars — people, institutions, dates, populations or figures — traceable to the source.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE1-2",rule:"The context contains a fact that resists the obvious reading.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE1-3",rule:"All three analysisPrompts require weighing, adjudication or falsification, and use three different stems.",check:"regex",polarity:"forbid",re:new RegExp("^(What is|Define|Describe|List|Identify) ","i")},{id:"UNI-CASE1-4",rule:"keyInsight states a defeasible claim and names what it rests on; it is not a restatement of the Card 1 definition.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE1-5",rule:"The case is left open in the direction Card 6 will contradict; it does not close on a settled conclusion.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE1-6",rule:"The case includes something genuinely unexpected or counter-intuitive about the outcome - not a clean, predictable illustration of the theory.",check:"regex",polarity:"require",re:new RegExp("\\bunexpected\\b|\\bsurprising(ly)?\\b|\\bcounter-?intuitively\\b|\\bcontrary to (what|expectations)\\b","i")}]},"case-study-2":{intent:"Put a second, differently-situated case against the first so the student has to adjudicate between two defensible readings rather than absorb one.",prompt:"Different setting, different population and different particulars from Card 5. Not the same case relocated.\nThis case must reach a conclusion in tension with Card 5's keyInsight: the same framework applied and getting a different result, or two frameworks giving different verdicts on comparable facts. If both cases illustrate the same conclusion, this one is decoration.\nSay explicitly where the two cases part company, and on which fact.\nThe three analysisPrompts differ from Card 5's in stem type, not only in wording. At least one must ask the student to decide which case's reading generalises and on what grounds.\ncriticalReflection names what evidence would settle the disagreement — the study that has not been run, the measure nobody has, the comparison the field avoids. Never \"this shows the importance of considering multiple perspectives\".\nKeep every name, date and figure traceable to the reference material.\nWorked example - PASS: case-study-1 concludes the effect holds broadly; case-study-2 is a case where the same mechanism produces the opposite result, and the card states plainly that the first case's conclusion does not survive contact with this one. Worked example - FAIL: a second, unrelated example that merely illustrates the same theory again from a different angle.\nWorked example - PASS: case-study-1 concludes the effect holds broadly; case-study-2 is a case where the same mechanism produces the opposite result, and the card states plainly that the first case's conclusion does not survive contact with this one. Worked example - FAIL: a second, unrelated example that merely illustrates the same theory again from a different angle.\nWorked example - PASS: case-study-1 concludes the effect holds broadly; case-study-2 is a case where the same mechanism produces the opposite result, and the card states plainly that the first case's conclusion does not survive contact with this one. Worked example - FAIL: a second, unrelated example that merely illustrates the same theory again from a different angle.",criteria:[{id:"UNI-CASE2-1",rule:"The setting, population and particulars differ from Card 5.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE2-2",rule:"The conclusion is in tension with Card 5's keyInsight, and the point of divergence is named.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE2-3",rule:"The three analysisPrompts differ from Card 5's in stem type, not only in wording.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE2-4",rule:"criticalReflection names the evidence that would settle the disagreement.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE2-5",rule:"The context carries its own named particulars from the source; none are carried over from Card 5.",check:"judgement",polarity:null,re:null},{id:"UNI-CASE2-6",rule:"The card explicitly references or contrasts with the named case from case-study-1 - the two cases are one argument in two parts, not two unrelated examples.",check:"continuity",polarity:"require",re:null,anchor:"case-study-1"}]},"decision-point":{intent:"Test the adjudication the previous six cards built — which reading the evidence supports — with three wrong answers that are named reasoning errors a good student would defend.",prompt:'Set the question in a situation with evidence in it: the finding, the design, the number. Never "Which of the following best defines…". A student who has memorised the key terms must not be able to answer it.\nThe question must require at least one framework, limitation or case from Cards 2 to 6, named or unmistakably invoked.\nAll four options are 10 to 16 words, the same level of detail, each stating a position rather than a definition. Do not append reasoning to the correct option that the wrong ones do not carry.\nEach wrong answer is a specific, named reasoning error a capable student would defend: a framework applied outside the limits stated on Card 2, an inference the evidence permits but does not support, correlation read as mechanism, or the right answer to a neighbouring question.\nFeedback on every option says why someone would hold it, then names the reasoning error by its name, and contains a fact from the pack. A marker should be able to say which misreading each wrong answer represents.',criteria:[{id:"UNI-DECISION-1",rule:"The question is situational and cannot be answered from the keyTerms alone.",check:"regex",polarity:"forbid",re:new RegExp("^(Which of the following|What is the definition|How do you ensure)","i")},{id:"UNI-DECISION-2",rule:"Answering requires a framework, limitation or case from Cards 2 to 6.",check:"judgement",polarity:null,re:null},{id:"UNI-DECISION-3",rule:"All four options are 10-16 words with matching detail; the correct one is not the longest, and no option carries an absolutist marker.",check:"judgement",polarity:null,re:null},{id:"UNI-DECISION-4",rule:"Each wrong answer is a specific reasoning error a capable student would defend, not carelessness.",check:"judgement",polarity:null,re:null},{id:"UNI-DECISION-5",rule:"Each feedback string names the reasoning error by name and contains a fact from the pack.",check:"judgement",polarity:null,re:null},{id:"UNI-DECISION-6",rule:"The correct option is a position that could have been argued the other way, not the only non-absurd choice.",check:"judgement",polarity:null,re:null}]}},topicstext:{overview:{intent:"Establish what the subject is in one standalone sentence, then state what is measurably different in the world for someone who has grasped it - so the article has a reader before it has a topic.",prompt:"Paragraph 1 opens with a plain definitional sentence: name the subject and place it in its broadest true category. No metaphor, no question, no anecdote, no statistic in that first sentence. Then narrow: what it is made of, what it operates on, what distinguishes it from the nearest neighbouring thing.\nParagraph 2 states what changes in the world because of this subject - a consequence, a cost, a decision that goes differently, a thing that becomes possible or stops being possible. State it about the world, not about the reader's understanding. Name who or what is affected and by how much.\nAt least one dated, named or quantified particular must appear in each paragraph: a year, a figure, a named work, a named process, a named place, a named person.\nThe keyTakeaway carries the load-bearing figure or named fact of the whole slide, not a restatement of the definition.",criteria:[{id:"TT-OVERVIEW-1",rule:"The first sentence of paragraphs[0] is a true classificatory definition of the subject that survives being read alone.",check:"judgement",polarity:null,re:null},{id:"TT-OVERVIEW-2",rule:"The first sentence contains no metaphor opener, no question, and no statistic.",check:"regex",polarity:"forbid",re:new RegExp("^(Imagine|Picture|Think of|Consider|Have you|Like a|It is like)\\b","i")},{id:"TT-OVERVIEW-3",rule:"paragraphs[1] states a consequence in the world, not a benefit to the learner's understanding.",check:"judgement",polarity:null,re:null},{id:"TT-OVERVIEW-4",rule:"Each paragraph carries at least one dated, named or quantified particular drawn from the reference material.",check:"judgement",polarity:null,re:null},{id:"TT-OVERVIEW-5",rule:"The keyTakeaway carries a figure, threshold or named thing and does not open with an understanding verb.",check:"judgement",polarity:null,re:null},{id:"TT-OVERVIEW-6",rule:"The overview does not restate the card heading or the topic name as its content.",check:"judgement",polarity:null,re:null},{id:"TT-OVERVIEW-7",rule:"Somewhere in the opening, a contrast or surprise marker (but/yet/contrary to/in fact) sits next to a concrete figure - since the conventional hook devices are banned on this card, this is the route's substitute for one.",check:"regex",polarity:"require",re:new RegExp("\\b(but|yet|surprisingly|contrary to|unlike what|counter-?intuitively|in fact)\\b[^.]{0,80}\\d|\\d[^.]{0,80}\\b(but|yet|surprisingly|contrary to|unlike what|counter-?intuitively|in fact)\\b","i")}]},"key-concepts":{intent:"Give the two or three ideas the rest of the article depends on, each as a distinction with a named mechanism, and three or four terms a reader could learn from a flip card alone.",prompt:'Carry two or three load-bearing ideas, no more. Prefer ideas that are DISTINCTIONS - X as against Y - over ideas that are only labels. For each: name it, define it in one sentence, then say what work it does in the subject.\nGive each idea as a mechanism with its middle step named, not as an outcome. Say what happens, in what order, to what. Attach its figure, threshold or date where the reference material supplies one.\nGive the simplest complete version of each idea, never a simplification that must be retracted later.\nkeyTerms are taken from these two paragraphs and no others. Each definition must not contain the term itself and must not open with "This is", "It is" or "These are". These render as flip cards, so a reader who sees only the definition should be able to name the term.',criteria:[{id:"TT-CONCEPTS-1",rule:"At least one of the ideas is stated as a distinction between two things, with what separates them named.",check:"regex",polarity:"require",re:new RegExp("\\b(rather than|as against|not to be confused with|differs from|unlike|whereas|as opposed to)\\b")},{id:"TT-CONCEPTS-2",rule:"Each idea carries a mechanism with a named intermediate step, not only its outcome.",check:"judgement",polarity:null,re:null},{id:"TT-CONCEPTS-3",rule:"Every keyTerm definition does not contain the term and does not open with this/it/these.",check:"judgement",polarity:null,re:null},{id:"TT-CONCEPTS-4",rule:"Every keyTerm appears in the two paragraphs of this same card.",check:"judgement",polarity:null,re:null},{id:"TT-CONCEPTS-5",rule:"No more than three ideas are introduced, and each carries a figure, date, named work or named process.",check:"judgement",polarity:null,re:null},{id:"TT-CONCEPTS-6",rule:"Nothing on this card is defined by restating its own name.",check:"regex",polarity:"forbid",re:new RegExp("\\b(is the process of|refers to the idea that|is when you|is all about)\\b")},{id:"TT-CONCEPTS-7",rule:"At least one key concept is tied to a concrete consequence for a specific kind of person, not just an abstract definition.",check:"regex",polarity:"require",re:new RegExp("\\b(if you (get|miss|skip)|means (a|the|you)|can (cost|cause|lead to)|the (result|consequence) is|puts? (a|the) (worker|patient|customer|student|driver) at)\\b","i")}]},"examples-application":{intent:"Put the card 2 ideas into two genuinely different real cases that come out differently, so the reader sees where the idea bends rather than seeing it confirmed twice.",prompt:'Give exactly two concrete cases, settings or contexts - one per paragraph - and show what the ideas from card 2 look like in each. The two cases must reach DIFFERENT results: the same idea applied and buying different things, or one case where the idea holds and one where it stops holding. Two cases that both confirm the same point teach half as much as two that diverge.\nName real particulars in each: a place, a year, a role, a figure, a named work, a named method, a decision that was made.\nAt least one sentence must take the form "X rather than Y, because...", saying what each option buys and at what cost.\nIntroduce no concept that was not named on card 2. An example of something the reader has not been given is a second article starting.',criteria:[{id:"TT-EXAMPLES-1",rule:'One sentence has the form "X rather than Y, because..." with a real trade named on both sides.',check:"regex",polarity:"require",re:new RegExp("(rather than|instead of|as against)[^.]{0,120}\\b(because|since)\\b")},{id:"TT-EXAMPLES-2",rule:"The two cases reach different results; the card states what separates them.",check:"judgement",polarity:null,re:null},{id:"TT-EXAMPLES-3",rule:"Each paragraph names at least two particulars - a place, year, role, figure, named work or named method.",check:"judgement",polarity:null,re:null},{id:"TT-EXAMPLES-4",rule:"No concept or defined term appears here that does not appear on card 2.",check:"judgement",polarity:null,re:null},{id:"TT-EXAMPLES-5",rule:"The examples are cases, not restatements - each names an actual decision someone took and what followed.",check:"regex",polarity:"forbid",re:new RegExp("\\b(can be applied|is used in|plays a role in|is relevant to|various contexts)\\b")},{id:"TT-EXAMPLES-6",rule:"At least one example names a concrete consequence for a specific kind of person, not just an abstract situation.",check:"regex",polarity:"require",re:new RegExp("\\b(if (you|a|the) (worker|patient|customer|student|driver|reader))\\b|\\b(costs?|causes?|results? in|leads? to) (a|the) (worker|patient|customer|student|driver)\\b","i")}]},"key-takeaways":{intent:"Compress what must survive, then name the specific wrong belief a real reader arrived holding and take it away from them - the route's substitute for making a learner commit.",prompt:'Paragraph 1: the points that must survive if the reader forgets everything else, written as prose and not as a list. Say why each one holds, not that it is important. Carry the figures.\nParagraph 2: name the single most common mistaken belief about this subject - the one a reasonably intelligent person arrives holding. Say plainly that it is wrong, say why it is plausible, then give the correct account with its mechanism or figure. This paragraph MUST contain an explicit negation: "is not", "does not", "are not" or "contrary to".\ngoodItems and badItems become a drag-to-sort activity, so each must be judgeable alone, without the article in front of it. Each is a factual claim in declarative or imperative form. Every badItem must be plainly and checkably wrong, never merely weaker, and must carry no hedge. Pair them: each badItem is the mistaken version of one goodItem.',criteria:[{id:"TT-TAKEAWAYS-1",rule:"paragraphs[1] names a specific mistaken belief and negates it explicitly.",check:"regex",polarity:"require",re:new RegExp("\\b(is not|does not|are not|do not|contrary to|it is a mistake to)\\b")},{id:"TT-TAKEAWAYS-2",rule:"The mistaken belief is one a real reader would hold, and the card says why it is plausible before correcting it.",check:"judgement",polarity:null,re:null},{id:"TT-TAKEAWAYS-3",rule:"Each of the six sort items is judgeable in isolation.",check:"judgement",polarity:null,re:null},{id:"TT-TAKEAWAYS-4",rule:"Every badItem is plainly wrong on a matter of fact, not merely weaker practice, and carries no hedge.",check:"judgement",polarity:null,re:null},{id:"TT-TAKEAWAYS-5",rule:"Each badItem is the mistaken counterpart of one goodItem, so the pair discriminates rather than lists.",check:"judgement",polarity:null,re:null},{id:"TT-TAKEAWAYS-6",rule:"Neither paragraph nor any item is a virtue, a vice or a generic professional habit.",check:"regex",polarity:"forbid",re:new RegExp("\\b(balanced|tailored|appropriate|optimal|best practice|staying informed|holistic)\\b","i")},{id:"TT-TAKEAWAYS-7",rule:"The takeaway states a genuine distinction or correction - what someone might wrongly assume, and what is actually true - not a restatement of the topic.",check:"regex",polarity:"require",re:new RegExp("\\b(it is not|is not the same as|contrary to|a common (mistake|assumption) is|many (assume|think))\\b","i")}]},"decision-point":{intent:"Force the reader's only overt commitment of the pack onto a discrimination between two defensible readings of the article, and correct the misconception by name in the feedback.",prompt:"Set the question in a situation with particulars - a year, a figure, a place, a case - not as a definition check. It must be answerable only by someone who followed the argument of cards 1 to 4, and unanswerable by someone who memorised a phrase from them.\nThe best wrong answer is the RIGHT answer to a neighbouring case: the correct rule applied at the wrong threshold, to the wrong period, or to the wrong material. At least two of the four options must be things a competent person might actually choose. Build at least one wrong option directly from the misconception named on card 4.\nEvery option names a specific action, judgement or figure. The correct option must not be the longest, the most detailed, or the only one carrying a justification clause.\nFeedback on every option says why someone would believe it, then what specifically is wrong, and includes a fact. Feedback that only predicts a bad result teaches nothing.",criteria:[{id:"TT-DECISION-1",rule:"The longest option is no more than 1.4 times the length of the shortest.",check:"judgement",polarity:null,re:null},{id:"TT-DECISION-2",rule:"The correct answer is not identifiable with the article covered.",check:"judgement",polarity:null,re:null},{id:"TT-DECISION-3",rule:"No option contains an absolutist or self-announcing wrongness marker.",check:"regex",polarity:"forbid",re:new RegExp("\\b(solely|always|never|ignore|ignoring|overlook|disregard)\\b")},{id:"TT-DECISION-4",rule:"At least one wrong option is the misconception named in card 4, paragraph 2.",check:"judgement",polarity:null,re:null},{id:"TT-DECISION-5",rule:"Every option's feedback names why the choice is tempting, then what is wrong, and contains a fact.",check:"judgement",polarity:null,re:null},{id:"TT-DECISION-6",rule:"The question is situational and cannot be answered by defining a term.",check:"regex",polarity:"forbid",re:new RegExp("^(What is|Which of the following best defines|What does .{1,40} mean)")},{id:"TT-DECISION-7",rule:"The feedback on the wrong answer names the specific misconception that makes it tempting, not just that it is incorrect.",check:"regex",polarity:"require",re:new RegExp("\\b(tempting because|it (looks|seems|sounds) right because|easy to (assume|think)|the mistake is (thinking|assuming))\\b","i")}]}},general:{"hook-scenario":{intent:"ORIENT - create interest and connect the topic to something the learner already understands, so they have a reason to need what follows.",prompt:"Choose the opening technique that fits this topic - a situation, a misconception, a surprising fact, a question, a short story or a familiar example - rather than defaulting to a workplace scenario every time. Make the tempting wrong assumption understandable. Every detail must teach context, stakes, or set up a question Card 2 answers. Where a named character or setting helps continuity, establish them here for later cards.",criteria:[{id:"GEN-HOOK-1",rule:'The opening contains a concrete situation, example, fact or misconception rather than generic importance language ("this topic matters because...").',check:"judgement",polarity:null,re:null},{id:"GEN-HOOK-2",rule:"The card creates a question or prediction that Card 2 (Understand) can answer.",check:"judgement",polarity:null,re:null},{id:"GEN-HOOK-3",rule:"At least one consequence or stake is concrete and observable, not abstract.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Orient", "Introduction", "Overview" or "Getting Started".',check:"judgement",polarity:null,re:null}]},"concept-explainer":{intent:"UNDERSTAND - build the core idea the learner needs, choosing whichever explanatory structure fits this content best.",prompt:"Answer Card 1 directly. Pick the explanatory approach that fits: What/Why/How/Apply, an analogy bridging into the real mechanism, cause -> mechanism -> effect, the vital few concepts that matter most, a comparison, or a worked explanation. Explain why the obvious interpretation is incomplete or wrong where relevant. Keep any formal or source language accurate and make the concept usable, not just stated.",criteria:[{id:"GEN-CONCEPT-1",rule:"The explanation answers the uncertainty or misconception raised on Card 1.",check:"continuity",polarity:"require",re:null},{id:"GEN-CONCEPT-2",rule:"At least one insight explains cause, mechanism or a meaningful distinction rather than only describing importance.",check:"judgement",polarity:null,re:null},{id:"GEN-CONCEPT-3",rule:"Any named law, standard, study, threshold or formal rule is source-supported or omitted.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Understand", "Explanation" or the topic name repeated verbatim.',check:"judgement",polarity:null,re:null}]},mistakes:{intent:"EXPLORE - go deeper than Cards 1-2 by teaching a second concept, a misconception, a trade-off, an exception or a relationship the learner would otherwise miss. This is the card that stops the pack reading as intro + bullets + example + summary.",prompt:'Decide what "deeper" means for THIS topic: a second important concept, what beginners commonly misunderstand, a trade-off or exception, a relationship between two ideas already introduced, or evidence that complicates the simple version from Card 2. Frame each item as a mistake/consequence pair only where that is genuinely the deepening move - the underlying job is depth, not error-avoidance for its own sake. Each item must be one a capable learner could plausibly get wrong or miss, with a specific, non-generic consequence.',criteria:[{id:"GEN-MISTAKE-1",rule:"Each item is plausible, specific to the subject, and adds genuine depth beyond Cards 1-2 rather than restating them.",check:"judgement",polarity:null,re:null},{id:"GEN-MISTAKE-2",rule:"Each consequence teaches both the cost of getting it wrong and the corrective principle or distinction.",check:"judgement",polarity:null,re:null},{id:"GEN-MISTAKE-3",rule:"No two items are merely paraphrases of the same error or the same idea.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Explore", "Going Deeper" or "More Information".',check:"judgement",polarity:null,re:null}]},"mental-model":{intent:"APPLY - move understanding into practical use via the Instructional Model Router: select the model whose reasoning structure matches what the learner must actually DO with this content.",prompt:"Choose the model that fits the learning type from the Instructional Model Router (GROW for coaching, PDCA for improvement, 5 Whys for root cause, Cost-Benefit for decisions, Risk-Control for safety, Prepare-Perform-Check-Verify for procedure, Diagnose-Test-Correct-Verify for troubleshooting, Trigger-Behaviour-Consequence-Replacement for behaviour, What-Why-How-Apply for concepts, Compare-Contrast for comparison, Cause-Mechanism-Effect for cause/effect, and so on) - do not default to GROW or PDCA regardless of topic. Each step must be more than a label: include the decision/action, what the learner notices, why it matters, the error it prevents, and how the learner knows to continue or change course. Never surface the model's name as the card heading unless naming it genuinely helps the learner.",criteria:[{id:"GEN-MODEL-1",rule:"The steps form a usable reasoning/action sequence rather than acronym definitions.",check:"judgement",polarity:null,re:null},{id:"GEN-MODEL-2",rule:"At least one step contains a branch, boundary, diagnostic question or decision rule.",check:"judgement",polarity:null,re:null},{id:"GEN-MODEL-3",rule:"The selected model clearly fits the topic learning type rather than being a generic framework pasted onto it.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Apply", "Application", or the bare model name (e.g. "GROW Model").',check:"judgement",polarity:null,re:null}]},"decision-point":{intent:"CHALLENGE - require the learner to think WITH the knowledge from Cards 1-4, using whichever challenge type creates real cognitive friction for this topic.",prompt:'Choose the challenge type that fits: a realistic decision, spot-the-mistake, predict-the-outcome, choose-between-approaches, a diagnose task, a worked problem, a misconception challenge, a mini case study, or a "what would you do" prompt. The correct option must depend on understanding built across Cards 1-4, not on trivia or definition recall. Build distractors from real misconceptions, wrong boundaries, or the right rule misapplied to a neighbouring case. Feedback explains why each option is tempting and the exact reasoning that separates it from the best answer.',criteria:[{id:"GEN-DECISION-1",rule:"The question tests application or discrimination built on Cards 1-4, not definition recall or trivia.",check:"judgement",polarity:null,re:null},{id:"GEN-DECISION-2",rule:"All four options are parallel, plausible and similar in detail.",check:"judgement",polarity:null,re:null},{id:"GEN-DECISION-3",rule:"Wrong-answer feedback identifies the misconception or boundary error that made the option tempting.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Challenge" or "Test Your Knowledge".',check:"judgement",polarity:null,re:null}]},"competency-summary":{intent:'CONSOLIDATE - make the important learning easy to retrieve and use later, using whichever retention treatment fits: a practical playbook, a checklist, rules of thumb, an action plan, Start-Stop-Continue, a decision guide, memorable principles, a next-step routine, or a quick-reference method. Not a plain "Key Takeaways" recap.',prompt:"Treat this as a capability summary: what can the learner now recognise, explain, decide or do? Pair each good item with the misconception or weak move it replaces, drawing on what Cards 1-5 actually established rather than re-teaching the topic from scratch. Avoid virtues such as confidence or professionalism unless they are observable actions.",criteria:[{id:"GEN-SUMMARY-1",rule:"Good items describe observable understanding, decisions or actions.",check:"judgement",polarity:null,re:null},{id:"GEN-SUMMARY-2",rule:"Bad items name specific misconceptions or failure patterns, not character flaws.",check:"judgement",polarity:null,re:null},{id:"GEN-SUMMARY-3",rule:"The summary adds retrieval/consolidation value rather than repeating Card 5 (Challenge) verbatim.",check:"judgement",polarity:null,re:null},{id:"GEN-TITLE-1",rule:'title is a specific, topic-grounded heading - never a generic label such as "Consolidate", "Summary", "Key Takeaways" or "Conclusion".',check:"judgement",polarity:null,re:null}]}}};return{CARD_QUALITY:e,getCardQuality:function(t,n){var a=e[t];return a&&a[n]||null},renderCardQuality:function(t,n){var a=e[t];if(!a)return"";var o=["","QUALITY STANDARD FOR EACH CARD  -  this is what the card is judged against.","These are not style notes. A card that misses them is regenerated.",""];return(n||Object.keys(a)).forEach(function(e,t){var n=a[e];n&&(o.push("CARD "+(t+1)+" - "+e.toUpperCase()),o.push("WHAT IT IS FOR: "+n.intent),o.push(n.prompt),o.push("IT IS CHECKED FOR:"),n.criteria.forEach(function(e){o.push("  - "+e.rule)}),o.push(""))}),o.join("\n")}}});
